trigger.script:
if IsQuestTaken("CombatInKollizey_Quest1") and not(IsQuestComplete("CombatInKollizey_Quest1") or IsQuestFailed("CombatInKollizey_Quest1")) then TActivate( "RolikBegin_Kolizey1" )
trigger:Deactivate() end
if IsQuestTaken("r1m2_GoToArena_Quest") and not(IsQuestComplete("r1m2_GoToArena_Quest") or IsQuestFailed("r1m2_GoToArena_Quest")) then TActivate( "RolikBegin_Kolizey2" )
trigger:Deactivate() end

local amount = trigger:GetTriggeredObjectAmount() for i=0, amount-1 do local guestID = trigger:GetTriggeredObjectID(i) local guest = getObj(guestID) if guest then local name = guest:GetName()
if strsub(name,1,10)=="FormulaCar" then local locname = trigger:GetCallObjName() local locnum = tonumber(strsub(locname,12,13))
local carnum=tonumber(strsub(name,11,11)) local canmovearr = {{1,2,2},{1,2,3},{2,2,3}}
local let = {"L","M","R"} local nums = GetVar("CarCurSide"..carnum).AsInt
local newnums = canmovearr[nums][random(3)] SetVar("CarCurSide"..carnum,newnums)
local nextpath = "Gonka_"..locnum.."-"..(locnum+1).."_"..let[newnums] guest:SetExternalPathByName(nextpath) end end end -- trigger:Deactivate()
